import json
def solve(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    vert5=[c for c in range(w) if sum(1 for r in range(h) if g[r][c]==5)>=4]
    horz5=[r for r in range(h) if sum(1 for c in range(w) if g[r][c]==5)>=4]
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (0,5)]
    rs=[r for r,c,v in cells]; cs=[c for r,c,v in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    pat=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    if vert5 and not horz5:
        lc=max(vert5)
        lr=[r for r in range(h) if g[r][lc]==5]; rtop=min(lr); rbot=max(lr)
        for r in range(rtop,r1+1):
            for c in range(c0,c1+1):
                out[r][c]=pat[(r-r0)%len(pat)][c-c0]
    elif horz5 and not vert5:
        ra=max(horz5)
        cr=[c for c in range(w) if g[ra][c]==5]; cl=min(cr); crt=max(cr)
        for c in range(cl,crt+1):
            for r in range(r0,r1+1):
                out[r][c]=pat[r-r0][(c-cl)%len(pat[0])]
    return out
